package com.bank.analytics.service;

import com.bank.analytics.model.TierNode;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates all structurally unique BST shapes over tiers 1..n.
public class BstShapesService {
    private static final Logger log = Logger.getLogger(BstShapesService.class.getName());

    public List<TierNode> allShapes(int n) {
        if (n == 0) {
            return new ArrayList<>();
        }
        List<TierNode> shapes = generate(1, n);
        log.info(() -> "Generated " + shapes.size() + " BST shapes for n=" + n);
        return shapes;
    }

    private List<TierNode> generate(int start, int end) {
        List<TierNode> result = new ArrayList<>();
        if (start > end) {
            result.add(null); // empty-range sentinel enables pairing
            return result;
        }
        for (int i = start; i <= end; i++) {
            List<TierNode> leftTrees = generate(start, i - 1);
            List<TierNode> rightTrees = generate(i + 1, end);
            for (TierNode l : leftTrees) {
                for (TierNode r : rightTrees) {
                    TierNode root = new TierNode(i);
                    root.setLeft(l);
                    root.setRight(r);
                    result.add(root);
                }
            }
        }
        return result;
    }

    // Render a tree as a parenthesized string for logging.
    public String render(TierNode node) {
        if (node == null) {
            return ".";
        }
        return "(" + render(node.getLeft()) + node.getTier() + render(node.getRight()) + ")";
    }
}
