package com.bank.analytics;

import com.bank.analytics.model.TierNode;
import com.bank.analytics.service.BstShapesService;
import java.util.List;
import java.util.logging.Logger;

public class BstShapesApplication {
    private static final Logger log = Logger.getLogger(BstShapesApplication.class.getName());

    public static void main(String[] args) {
        BstShapesService service = new BstShapesService();
        List<TierNode> shapes = service.allShapes(3);
        for (TierNode shape : shapes) {
            log.info("NBI tier BST shape: " + service.render(shape));
        }
    }
}
